    function getAssigneeCount(uint256 resource, uint256 roleBitmap)
        public
        view
        virtual
        returns (uint256 counts, uint256 mask)
    {
        mask = _roleBitmapToMask(roleBitmap);
        counts = _roleCount[resource] & mask;
    }

